import {Box, SegmentedRadioGroup, Spin} from '@gravity-ui/uikit';
import React, {Suspense, useState} from 'react';

import type {
    LazyVisualizationEngine,
    VisualizationMode,
    VisualizationWidgetData,
} from './types';
import './VisualizationWidget.css';

const engines: Record<VisualizationMode, LazyVisualizationEngine> = {
    sales: React.lazy(() =>
        import('./SalesChart').then((module) => ({default: module.SalesChart})),
    ),
    monitoring: React.lazy(() =>
        import('./MonitoringChart').then((module) => ({
            default: module.MonitoringChart,
        })),
    ),
};

const modeOptions: Array<{value: VisualizationMode; content: string}> = [
    {value: 'sales', content: 'Продажи'},
    {value: 'monitoring', content: 'Мониторинг'},
];

interface VisualizationWidgetProps {
    data: VisualizationWidgetData;
}

export function VisualizationWidget({data}: VisualizationWidgetProps) {
    const [mode, setMode] = useState<VisualizationMode>(data.mode);
    const Engine = engines[mode];
    const hasModeData = mode === 'sales' ? Boolean(data.sales) : Boolean(data.monitoring);

    return (
        <Box className="visualization-widget">
            <SegmentedRadioGroup
                aria-label="Режим визуализации"
                name="visualization-mode"
                size="m"
                value={mode}
                onUpdate={setMode}
                options={modeOptions}
            />
            <Box className="visualization-widget__chart">
                <Suspense fallback={<Spin size="m" />}>
                    {hasModeData ? <Engine data={data} /> : null}
                </Suspense>
            </Box>
        </Box>
    );
}
import YagrComponent from '@gravity-ui/yagr/react';
import '@gravity-ui/yagr/index.css';

import type {VisualizationEngineProps} from './types';

export function MonitoringChart({data}: VisualizationEngineProps) {
    const monitoring = data.monitoring;

    if (!monitoring) {
        return null;
    }

    return (
        <YagrComponent
            id="monitoring-realtime-chart"
            config={{
                timeline: monitoring.timeline,
                series: monitoring.series.map((series) => ({
                    name: series.name,
                    color: series.color,
                    data: series.data,
                    type: 'line' as const,
                    scale: 'y',
                })),
                scales: {y: {}},
                chart: {
                    appearance: {
                        theme: 'light',
                    },
                    size: {
                        adaptive: true,
                    },
                },
                cursor: {
                    snapToValues: false,
                },
            }}
        />
    );
}
import {Chart} from '@gravity-ui/charts';

import type {VisualizationEngineProps} from './types';

export function SalesChart({data}: VisualizationEngineProps) {
    const sales = data.sales;

    if (!sales) {
        return null;
    }

    return (
        <Chart
            lang="ru"
            data={{
                xAxis: {type: 'datetime'},
                series: {
                    data: sales.series.map((series) => ({
                        type: 'line' as const,
                        name: series.name,
                        data: series.data,
                    })),
                },
            }}
        />
    );
}
import type * as React from 'react';

export type VisualizationMode = 'sales' | 'monitoring';

export interface SalesSeries {
    name: string;
    data: Array<{x: number; y: number | null}>;
}

export interface MonitoringSeries {
    name: string;
    color: string;
    data: Array<number | null>;
}

export interface VisualizationWidgetData {
    mode: VisualizationMode;
    sales?: {series: SalesSeries[]};
    monitoring?: {timeline: number[]; series: MonitoringSeries[]};
}

export interface VisualizationEngineProps {
    data: VisualizationWidgetData;
}

export type LazyVisualizationEngine = React.LazyExoticComponent<
    React.ComponentType<VisualizationEngineProps>
>;
.visualization-widget {
    --chart-height: 320px;

    padding: var(--g-spacing-4);
}

.visualization-widget__chart {
    height: var(--chart-height);
    margin-top: var(--g-spacing-4);
}

